<div class="card mb-3"><div class="card-header">Tambah administrator</div><div class="card-body"><?= form_open('admin/pengguna/tambah',array('class'=>'row g-2')) ?>
<div class="col-md-3"><input name="nama" class="form-control" placeholder="Nama" required></div><div class="col-md-3"><input type="email" name="email" class="form-control" placeholder="Email" required></div><div class="col-md-3"><input name="password" class="form-control" placeholder="Password (min. 8)" minlength="8" required></div><div class="col-md-2"><button class="btn btn-sisapi w-100">Tambah</button></div><?= form_close() ?></div></div>
<div class="card"><div class="card-body table-responsive"><table class="table"><thead><tr><th>Nama</th><th>Email</th><th>Login terakhir</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($list as $u): ?><tr><td><?= e($u->nama) ?></td><td><?= e($u->email) ?></td><td><?= tgl($u->last_login) ?></td><td><?= $u->is_active?'<span class="badge bg-success">Aktif</span>':'<span class="badge bg-secondary">Nonaktif</span>' ?></td>
<td><?php if($u->id!=$me['id']): ?><?= form_open('admin/pengguna/toggle/'.$u->id) ?><button class="btn btn-sm btn-outline-secondary"><?= $u->is_active?'Nonaktifkan':'Aktifkan' ?></button><?= form_close() ?><?php else: ?><small class="text-muted">Anda</small><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
